20261102:ol:OL27203W"},"before":null,"after":{"title":"The Four Agreements","author_id":"@a2","first_publish_year":1997,"open_library_id":"OL27203W","cover_id":13768599,"source_type":"open_library","work_type":null,"native_identity_key":"nlscale:20261102:ol:OL27203W","id":987100002}},{"ref":"e2","relation":"editions","key":{"open_library_edition_id":"OL47304083M"},"before":null,"after":{"work_id":"@w2","open_library_edition_id":"OL47304083M","isbn_13":"9789020212587","isbn_10":null,"language":"dut","publisher":"AnkhHermes, Uitgeverij","title":"De vier inzichten","id":987200002,"publish_date":null,"cover_id":13768599}},{"ref":"d2","relation":"catalog_work_descriptions","key":{"work_id":"@w2","language":"nl"},"before":null,"after":{"work_id":"@w2","language":"nl","bound_author_id":"@a2","text":"Don Miguel Ruiz beschrijft hoe aangeleerde overtuigingen onze omgang met onszelf en anderen kunnen bepalen. Vanuit zijn uitleg van de Tolteekse traditie werkt hij vier uitgangspunten voor het dagelijks leven uit. Daarbij bespreekt hij zorgvuldig spreken, het verschil tussen andermans gedrag en je eigenwaarde, het toetsen van aannames en de grenzen van je eigen inspanning. Het boek presenteert deze gedachten als een spirituele oefenweg, met aandacht voor verantwoordelijkheid en persoonlijke vrijheid.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://www.ankh-hermes.nl/boek/de-vier-inzichten/","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p398376875"],"checked_at":"2026-11-02T15:25:00.000Z","reference":"ol:OL27203W"},{"type":"original_substantive_source_review","sources":["https://www.ankh-hermes.nl/boek/de-vier-inzichten/","https://openlibrary.org/works/OL27203W","https://data.bibliotheken.nl/id/nbt/p398376875"],"review":"content-review-001.json"},{"type":"cover_front_review","cover_id":13768599,"sha256":"b5545acbfcea0b595ab15544c749560116d234641ef04ddf80c2678