first_publish_year":2016,"open_library_id":"OL17634924W","cover_id":8738182,"source_type":"open_library","work_type":"novel","native_identity_key":"nlscale:20261102:ol:OL17634924W","id":987100005}},{"ref":"e5","relation":"editions","key":{"open_library_edition_id":"OL27098692M"},"before":null,"after":{"work_id":"@w5","open_library_edition_id":"OL27098692M","isbn_13":"9789000345472","isbn_10":null,"language":"dut","publisher":"UNIEBOEK | HET SPECTRUM","title":"De hamer van Thor","id":987200005,"publish_date":null,"cover_id":8738182}},{"ref":"d5","relation":"catalog_work_descriptions","key":{"work_id":"@w5","language":"nl"},"before":null,"after":{"work_id":"@w5","language":"nl","bound_author_id":969300015,"text":"Magnus Chase probeert te wennen aan zijn bestaan in Hotel Walhalla, maar rust blijkt opnieuw van korte duur. De hamer van Thor is nog altijd zoek en vijanden van de god willen die macht graag in handen krijgen. Bovendien zijn twee vrienden verdwenen en veroorzaakt een nieuwe medebewoner problemen. Magnus moet in actie komen terwijl hij zijn plaats tussen de uitverkoren strijders nog zoekt. De zoektocht voert hem verder door de wereld van Noordse goden en hun onderlinge conflicten.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://openlibrary.org/works/OL17634924W","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p404993958"],"checked_at":"2026-11-02T15:25:00.000Z","reference":"ol:OL17634924W"},{"type":"original_substantive_source_review","sources":["https://openlibrary.org/works/OL17634924W","https://data.bibliotheken.nl/id/nbt/p404993958"],"review":"content-review-001.json"},{"type":"cover_front_review","cover_id":8738182,"sha256":"78b8a0f737a84a4409477f1b1e7e712118c3f2418f95c59b6296105b96f3ba8a","reference":"cover-semantic-review-001.json","limitation":"Front title/author and exact source-edition mapping; no visible barcode claim."}],"proven