publisher":"A. W. Bruna Uitgevers, B.V.","title":"De mammoetjagers","id":987200007,"publish_date":null,"cover_id":14417367}},{"ref":"d7","relation":"catalog_work_descriptions","key":{"work_id":"@w7","language":"nl"},"before":null,"after":{"work_id":"@w7","language":"nl","bound_author_id":"@a6","text":"Ayla trekt met Jondalar naar het volk van de mammoetjagers. Bij de Mamutoi vindt ze mensen die haar vaardigheden waarderen, maar hun taal en gebruiken vragen veel van haar. Terwijl ze aansluiting zoekt, ontstaat er ook spanning rond haar band met Jondalar. De aandacht van ivoorsnijder Ranec maakt hun verhouding ingewikkelder. Tegen de achtergrond van het leven in de ijstijd moet Ayla bepalen waar zij thuishoort en welke toekomst zij voor zichzelf wil.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://openlibrary.org/works/OL2746372W","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p237963213"],"checked_at":"2026-11-02T15:25:00.000Z","reference":"ol:OL2746372W"},{"type":"original_substantive_source_review","sources":["https://openlibrary.org/works/OL2746372W","https://data.bibliotheken.nl/id/nbt/p237963213"],"review":"content-review-002.json"},{"type":"cover_front_review","cover_id":14417367,"sha256":"b6f7e8330af1fb0d06a14357a6a6ae6bf626565c1c4e8f849535fd312ceefacf","reference":"cover-semantic-review-001.json","limitation":"Front title/author and exact source-edition mapping; no visible barcode claim."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-02T15:25:00.000Z","review_batch":"nl-scale-20261102-001"}},{"ref":"m7","relation":"catalog_edition_metadata","key":{"edition_id":"@e7"},"before":null,"after":{"edition_id":"@e7","work_id":"@w7","bound_author_id":"@a6","bound_title":"De mammoetjagers","bound_language":"dut","bound_isbn13":"9789022986202","format":"hardcover","cover_url":"https://covers.openlibrary.org/b/id/14417367-L.jpg?default=false","card_cover_url":"https://covers.openlibrary.org/b/id/14417367-M.jpg?default=false","evidence_url":"https://data.bibliotheken.nl/id/nbt/p237963213","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p237963213"],"checked_at":"2026-11-02T15:25:00.000Z","reference":"ol:OL2746372W"},{"type":"original_substantive_source_review","sources":["https://openlibrary.org/works/OL2746372W","https://data.bibliotheken.nl/id/nbt/p237963213"],"review":"content-review-002.json"},{"type":"cover_front_review","cover_id":14417367,"sha256":"b6f7e8330af1fb0d06a14357a6a6ae6bf626565c1c4e8f849535fd312ceefacf","reference":"cover-semantic-review-001.json","limitation":"Front title/author and exact source-edition mapping; no visible barcode claim."}],"review_status":"approved","reviewed_at":"2026-11-02T15:25:00.000Z","review_batch":"nl-scale-20261102-001"}},{"ref":"w8","relation":"works","key":{"native_identity_key":"nlscale:20261102:ol:OL2746368W"},"before":null,"after":{"title":"The Valley of Horses","author_id":"@a6","first_publish_year":1982,"open_library_id":"OL2746368W","cover_id":12528958,"source_type":"open_library","work_type":"novel","native_identity_key":"nlscale:20261102:ol:OL2746368W","id":987100008}},{"ref":"e8","relation":"editions","key":{"open_library_edition_id":"OL27311951M"},"before":null,"after":{"work_id":"@w8","open_library_edition_id":"OL27311951M","isbn_13":"9789027421951","isbn_10":null,"language":"dut","publisher":"Unieboek | Het Spectrum","title":"De vallei van de paarden","id":987200008,"publish_date":null,"cover_id":12528958}},{"ref":"d8","relation":"catalog_work_descriptions","key":{"work_id":"@w8","language":"nl"},"before":null,"after":{"work_id":"@w8","language":"nl","bound_author_id":"@a6","text":"Nadat ze uit haar clan is verdreven, moet Ayla zonder hulp een bestaan opbouwen. Ze kent de wereld van de neanderthalers die haar hebben grootgebracht, maar zoekt ook naar mensen die op haarzelf lijken. In een afgelegen vallei vindt ze middelen om te overleven en benut ze haar vindingrijkheid. Haar veiligheid neemt toe, terwijl de eenzaamheid blijft. Nieuwe ontmoetingen brengen de mogelijkheid van verbondenheid binnen bereik en veranderen de richting van haar leven.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://openlibrary.org/works/OL2746368W","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p159565227"],"checked_at":"2026-11-02T15:25:00.000Z","reference":"ol:OL2746368W"},{"type":"original_substantive_source_review","sources":["https://openlibrary.org/works/OL2746368W","https://data.bibliotheken.nl/id/nbt/p159565227"],"review":"content-review-002.json"},{"type":"cover_front_review","cover_id":12528958,"sha256":"851936ff1734c18e7ebdc0c91230ba7e40df37a94324ea9c5835b65bd180f93e","reference":"cover-semantic-review-001.json","limitation":"Front title/author and exact source-edition mapping; no visible barcode claim."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-02T15:25:00.000Z","review_batch":"nl-scale-20261102-001"}},{"ref":"m8","relation":"catalog_edition_metadata","key":{"edition_id":"@e8"},"before":null,"after":{"edition_id":"@e8","work_id":"@w8","bound_author_id":"@a6","bound_title":"De vallei van de paarden","bound_language":"dut","bound_isbn13":"9789027421951","format":"paperback","cover_url":"https://covers.openlibrary.org/b/id/12528958-L.jpg?default=false","card_cover_url":"https://covers.openlibrary.org/b/id/12528958-M.jpg?default=false","evidence_url":"https://data.bibliotheken.nl/id/nbt/p159565227","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p159565227"],"checked_at":"2026-11-02T15:25:00.000Z","reference":"ol:OL2746368W"},{"type":"original_substantive_source_review","sources":["https://openlibrary.org/works/OL2746368W","https://data.bibliotheken.nl/id/nbt/p159565227"],"review":"content-review-002.json"},{"type":"cover_front_review","cover_id":12528958,"sha256":"851936ff1734c18e7ebdc0c91230ba7e40df37a94324ea9c5835b65bd180f93e","reference":"cover-semantic-review-001.json","limitation":"Front title/author and exact source-edition mapping; no visible barcode claim."}],"review_status":"approved","reviewed_at":"2026-11-02T15:25:00.000Z","review_batch":"nl-scale-20261102-001"}},{"ref":"w9","relation":"works","key":{"native_identity_key":"nlscale:20261102:ol:OL19729677W"},"before":null,"after":{"title":"Why I''m No Longer Talking to White People About Race","author_id":"@a7","first_publish_year":2017,"open_library_id":"OL19729677W","cover_id":10473586,"source_type":"open_library","work_type":null,"native_identity_key":"nlscale:20261102:ol:OL19729677W","id":987100009}},{"ref":"e9","relation":"editions","key":{"open_library_edition_id":"OL30570783M"},"before":null,"after":{"work_id":"@w9","open_library_edition_id":"OL30570783M","isbn_13":"9789463104715","isbn_10":null,"language":"dut","publisher":"Polis","title":"Waarom ik niet meer met witte mensen over racisme praat","id":987200009,"publish_date":null,"cover_id":10473586}},{"ref":"d9","relation":"catalog_work_descriptions","key":{"work_id":"@w9","language":"nl"},"before":null,"after":{"work_id":"@w9","language":"nl","bound_author_id":"@a7","text":"Reni Eddo-Lodge onderzoekt waarom gesprekken over racisme zo vaak vastlopen. Vanuit haar ervaringen met het Britse debat kijkt ze naar geschiedenissen die weinig aandacht krijgen en naar de manier waarop ongelijkheid in het heden doorwerkt. Ook de samenhang tussen klasse en racisme komt aan bod. Het boek groeide uit een blog waarin zij haar frustratie uitsprak over discussies zonder voldoende ruimte voor degenen die de gevolgen ervaren. Die aanleiding wordt uitgewerkt tot een bredere maatschappelijke analyse.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://openlibrary.org/works/OL19729677W","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p424056194","http://data.bibliotheken.nl/id/nbt/p428452582"],"checked_at":"2026-11-02T15:25:00.000Z","reference":"ol:OL19729677W"},{"type":"original_substantive_source_review","sources":["https://openlibrary.org/works/OL19729677W","https://data.bibliotheken.nl/id/nbt/p424056194","https://data.bibliotheken.nl/id/nbt/p428452582"],"review":"content-review-002.json"},{"type":"cover_front_review","cover_id":10473586,"sha256":"281cd9a649e0f65e15a9d945a8a8e8fed5db35cffb87324b1158de8e13bfc9b2","reference":"cover-semantic-review-001.json","limitation":"Front title/author and exact source-edition mapping; no visible barcode claim."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-02T15:25:00.000Z","review_batch":"nl-scale-20261102-001"}},{"ref":"m9","relation":"catalog_edition_metadata","key":{"edition_id":"@e9"},"before":null,"after":{"edition_id":"@e9","work_id":"@w9","bound_author_id":"@a7","bound_title":"Waarom ik niet meer met witte mensen over racisme praat","bound_language":"dut","bound_isbn13":"9789463104715","format":"paperback","cover_url":"https://covers.openlibrary.org/b/id/10473586-L.jpg?default=false","card_cover_url":"https://covers.openlibrary.org/b/id/10473586-M.jpg?default=false","evidence_url":"https://data.bibliotheken.nl/id/nbt/p424056194","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p424056194","http://data.bibliotheken.nl/id/nbt/p428452582"],"checked_at":"2026-11-02T15:25:00.000Z","reference":"ol:OL19729677W"},{"type":"original_substantive_source_review","sources":["https://openlibrary.org/works/OL19729677W","https://data.bibliotheken.nl/id/nbt/p424056194","https://data.bibliotheken.nl/id/nbt/p428452582"],"review":"content-review-002.json"},{"type":"cover_front_review","cover_id":10473586,"sha256":"281cd9a649e0f65e15a9d945a8a8e8fed5db35cffb87324b1158de8e13bfc9b2","reference":"cover-semantic-review-001.json","limitation":"Front title/author and exact source-edition mapping; no visible barcode claim."}],"review_status":"approved","reviewed_at":"2026-11-02T15:25:00.000Z","review_batch":"nl-scale-20261102-001"}},{"ref":"w10","relation":"works","key":{"native_identity_key":"nlscale:20261102:ol:OL16518W"},"before":null,"after":{"title":"Eon","author_id":"@a8","first_publish_year":1985,"open_library_id":"OL16518W","cover_id":14413854,"source_type":"open_library","work_type":"novel","native_identity_key":"nlscale:20261102:ol:OL16518W","id":987100010}},{"ref":"e10","relation":"editions","key":{"open_library_edition_id":"OL47548308M"},"before":null,"after":{"work_id":"@w10","open_library_edition_id":"OL47548308M","isbn_13":"9789029042208","isbn_10":null,"language":"dut","publisher":"Meulenhoff","title":"Eon","id":987200010,"publish_date":null,"cover_id":14413854}},{"ref":"d10","relation":"catalog_work_descriptions","key":{"work_id":"@w10","language":"nl"},"before":null,"after":{"work_id":"@w10","language":"nl","bound_author_id":"@a8","text":"Wanneer een reusachtig object in de nabijheid van de aarde verschijnt, krijgt een periode van internationale dreiging een nieuwe wending. Onderzoekers treffen binnenin resten van een menselijke beschaving aan. De achtergelaten kennis lijkt te wijzen op een verwoestende oorlog en dwingt hen hun eigen toekomst opnieuw te bekijken. Verder in het object bevindt zich een doorgang die nog grotere vragen oproept. Het onderzoek verbindt een onbekende wereld met de politieke keuzes en angsten van de aarde.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://openlibrary.org/works/OL16518W","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p092692184"],"checked_at":"2026-11-02T15:25:00