ll,"after":{"work_id":"@w13","language":"nl","bound_author_id":"@a11","text":"Luc O''Donnell krijgt ongewenste aandacht doordat zijn beroemde vader weer in de belangstelling staat. Om zijn beschadigde imago te herstellen lijkt een keurige relatie een geschikte oplossing. Advocaat Oliver Blackwood heeft zelf een reden om met iemand op een belangrijke gelegenheid te verschijnen. Ze spreken af tijdelijk een stel te spelen, ondanks hun grote verschillen. Naarmate ze meer tijd met elkaar doorbrengen, wordt het steeds moeilijker hun afspraak van hun werkelijke gevoelens te scheiden.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://openlibrary.org/works/OL20840329W","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p430321112"],"checked_at":"2026-11-02T15:25:00.000Z","reference":"ol:OL20840329W"},{"type":"original_substantive_source_review","sources":["https://openlibrary.org/works/OL20840329W","https://data.bibliotheken.nl/id/nbt/p430321112","https://www.sourcebooks.com/9781728206141-boyfriend-material-tp.html","https://www.zomerenkeuning.nl/boek/boyfriend-material-paperback/"],"review":"content-review-004.json"},{"type":"cover_front_review","cover_id":13753741,"sha256":"30b852c4462a427aebc020e821680dfeaa116d89ea3988386f6ea893e17371f3","reference":"cover-semantic-review-001.json","limitation":"Front title/author and exact source-edition mapping; no visible barcode claim."}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-02T15:25:00.000Z","review_batch":"nl-scale-20261102-001"}},{"ref":"m13","relation":"catalog_edition_metadata","key":{"edition_id":"@e13"},"before":null,"after":{"edition_id":"@e13","work_id":"@w13","bound_author_id":"@a11","bound_title":"Boyfriend material","bound_language":"dut","bound_isbn13":"9789020541458","format":"paperback","cover_url":"https://covers.openlibrary.org/b/id/13753741-L.